<script setup>
import { ref,watch } from 'vue';
import { libraryApi } from '@/services/library.js';
import { ExternalLink,Download,RotateCcw } from 'lucide-vue-next';
const props=defineProps({unitId:String,compact:Boolean});
const unit=ref(null),error=ref(''),loading=ref(false),imageError=ref(false),attempt=ref(0);let generation=0;
async function load(){const id=props.unitId,version=++generation;unit.value=null;error.value='';imageError.value=false;attempt.value++;if(!id){error.value='没有指定原文位置，请从案例出处重新打开。';return}loading.value=true;try{const result=await libraryApi.unit(id);if(version===generation)unit.value=result}catch(e){if(version===generation)error.value=e.message}finally{if(version===generation)loading.value=false}}
watch(()=>props.unitId,load,{immediate:true});
</script>
<template><section class="source-reader"><p v-if="loading" role="status">读取原文中…</p><div v-else-if="error"><p role="alert" class="form-error">{{ error }}</p><Button variant="outline" @click="load"><RotateCcw :size="15" />重试</Button></div><template v-else-if="unit"><div class="source-reader-heading"><div><h2 v-if="!compact">{{ unit.materialTitle }}</h2><span>{{ unit.label }}</span></div><a :href="unit.originalUrl" target="_blank" rel="noopener"><Download :size="16" />原文件</a></div><p v-if="unit.metadata.author || unit.metadata.sourceNote" class="ops-source-credit">{{ [unit.metadata.author,unit.metadata.sourceNote].filter(Boolean).join(' · ') }}</p><a v-if="unit.metadata.sourceUrl" :href="unit.metadata.sourceUrl" target="_blank" rel="noopener" class="source-external">来源链接<ExternalLink :size="14" /></a><a v-if="unit.imageUrl" :href="unit.imageUrl+'?inline=1'" target="_blank" rel="noopener" class="original-preview"><img :src="unit.imageUrl+'?read='+attempt" @error="imageError=true" :alt="unit.materialTitle+' '+unit.label" /></a><div v-else class="source-document"><p class="model-prose">{{ unit.originalText }}</p><InfoTip label="Word阅读视图">此处按段落或表格还原文字，原始版式请下载原文件。</InfoTip></div><div v-if="imageError"><p role="alert" class="form-error">原文图片读取失败，请重试或下载原文件。</p><Button variant="outline" @click="load">重试原文图片</Button></div><details v-if="unit.text!==unit.originalText"><summary>修订后的识别文本</summary><p class="model-prose">{{ unit.text }}</p></details></template></section></template>
